import { createHash } from "node:crypto";
import { execFileSync } from "node:child_process";
import { copyFileSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { pathToFileURL } from "node:url";

const root = process.cwd();
const [mode, baseSha, capturedSha, reviewDirectory, reviewerFile, iterationArg] = process.argv.slice(2);
if (!["validate", "stage", "verify-commit"].includes(mode) || ![baseSha, capturedSha].every((value) => /^[a-f0-9]{40}$/u.test(value)))
  throw new Error("Expected mode, base SHA and immutable capture SHA");
const { experienceDigest, planProductExperience, validateExperienceEvidence, verifyProductExperience } =
  await import(pathToFileURL(resolve(root, "scripts/sounding-line/product-experience.mjs")).href);
const { pairedPublicationPathAllowed } =
  await import(pathToFileURL(resolve(root, "scripts/sounding-line/experience-paired.mjs")).href);
const git = (...args) => execFileSync("git", args, { encoding: "utf8", maxBuffer: 16 * 1024 * 1024 }).trim();
const lines = (output) => output.split(/\r?\n/u).filter(Boolean);
const json = (path) => JSON.parse(readFileSync(path, "utf8").replace(/^\uFEFF/u, ""));
const recordPath = "Development_Docs/Testing/Product_Experience/candidate-review.json";
const prefix = "Development_Docs/Testing/Product_Experience/evidence/harbor-901/" + capturedSha.slice(0, 12) + "/";
const receipts = ["development-capture-receipt.json", "media-transport.json"];
const safeTail = (tail) => tail.length && tail.split("/").every((part) => part && part !== "." && part !== ".." && !/[\\:]/u.test(part));
const changedSince = (base, candidate) => lines(git("diff", "--name-only", "--no-renames", base, candidate));
const planFor = (candidateSha) => planProductExperience({
  root, baseSha, candidateSha, changedPaths: changedSince(baseSha, candidateSha),
});
const references = (record) => [
  ...record.artifacts, record.pairedEvidence.report, record.pairedEvidence.runtime,
  record.pairedEvidence.profile, ...record.pairedEvidence.cases.map((item) => item.witness),
];

if (mode === "verify-commit") {
  const head = git("rev-parse", "HEAD");
  if (git("rev-parse", "HEAD^") !== capturedSha || git("rev-parse", "origin/main") !== baseSha)
    throw new Error("Publication ancestry changed");
  const evidence = JSON.parse(git("show", head + ":" + recordPath));
  const allowed = new Set([recordPath, ...receipts.map((name) => prefix + name), ...references(evidence).map((item) => item.path)]);
  const paths = changedSince(capturedSha, head);
  if (paths.length !== allowed.size || paths.some((path) => !allowed.has(path) || !pairedPublicationPathAllowed(path)))
    throw new Error("Publication includes an unexpected path or misses an evidence file");
  const plan = planFor(head);
  if (plan.sourceDigest !== evidence.sourceDigest || plan.contractDigest !== evidence.contractDigest ||
      verifyProductExperience(root, head, plan).status !== "PASS")
    throw new Error("Published evidence did not verify against the Git objects");
  console.log(JSON.stringify({ status: "PASS", baseSha, capturedSha, proofSha: head, files: paths.length, contracts: plan.contracts.length }));
} else {
  const iterations = Number(iterationArg);
  if (!Number.isInteger(iterations) || iterations < 1 || iterations > 3)
    throw new Error("Expected actual, supported review iteration");
  const media = resolve(reviewDirectory, "media");
  const capture = json(resolve(media, "capture.json"));
  const transport = json(resolve(media, "media-transport.json"));
  const plan = planFor(capturedSha);
  if (transport.candidateSha !== capturedSha || transport.baseSha !== baseSha ||
      capture.pairedEvidence.binding.candidateSha !== capturedSha ||
      capture.sourceDigest !== plan.sourceDigest || transport.sourceDigest !== plan.sourceDigest ||
      capture.contractDigest !== plan.contractDigest || transport.contractDigest !== plan.contractDigest ||
      transport.journeys !== capture.journeys.length ||
      JSON.stringify([...transport.contracts].sort()) !== JSON.stringify(plan.contracts.map((contract) => contract.id).sort()))
    throw new Error("Capture identity or contract scope changed");
  const originalPrefix = "artifacts/sounding-line/harbor-shared-experience/";
  const rebasePath = (artifact) => {
    if (!artifact.path.startsWith(originalPrefix) || !safeTail(artifact.path.slice(originalPrefix.length)))
      throw new Error("Invalid capture path " + artifact.path);
    return { ...artifact, path: prefix + artifact.path.slice(originalPrefix.length) };
  };
  const pairedIds = new Set(capture.pairedEvidence.cases.flatMap((item) => item.artifactIds));
  const record = {
    ...capture,
    artifacts: capture.artifacts.filter((artifact) => artifact.type !== "trace" || pairedIds.has(artifact.id)).map(rebasePath),
    pairedEvidence: {
      ...capture.pairedEvidence,
      report: rebasePath(capture.pairedEvidence.report),
      runtime: rebasePath(capture.pairedEvidence.runtime),
      profile: rebasePath(capture.pairedEvidence.profile),
      cases: capture.pairedEvidence.cases.map((item) => ({ ...item, witness: rebasePath(item.witness) })),
    },
  };
  const reviewed = new Map();
  for (const [folder, reviewerContext] of Object.entries(json(reviewerFile))) {
    if (!safeTail(folder) || typeof reviewerContext !== "string" || reviewerContext === "codex:/root")
      throw new Error("Invalid reviewer context");
    const input = json(resolve(reviewDirectory, folder, "review.json"));
    if (input.candidateSha !== capturedSha || input.sourceDigest !== plan.sourceDigest)
      throw new Error("Reviewer inspected a different source");
    for (const review of input.reviews) {
      if (reviewed.has(review.contractId) || review.status !== "ACCEPTED") throw new Error("Review requires correction: " + review.contractId);
      reviewed.set(review.contractId, { ...review, reviewerContext });
    }
  }
  if (reviewed.size !== plan.contracts.length) throw new Error("Independent review is incomplete");
  record.reviews = plan.contracts.map((contract) => {
    const review = reviewed.get(contract.id);
    if (!review) throw new Error("Missing review " + contract.id);
    const packetDigest = experienceDigest({
      sourceDigest: plan.sourceDigest, contract,
      artifacts: record.artifacts.filter((artifact) => artifact.contractId === contract.id).map(({ id, sha256 }) => ({ id, sha256 })),
      ...(contract.experience.pairedEvidence ? { pairedEvidence: record.pairedEvidence } : {}),
    });
    return {
      ...review, packetDigest, independence: "SEPARATE_CONTEXT", sourceInspectionOrder: "EXPERIENCE_BEFORE_SOURCE",
      builderContext: "codex:/root", iterations,
    };
  });
  const sourcePath = (file) => {
    if (!file.startsWith(prefix) || !safeTail(file.slice(prefix.length))) throw new Error("Artifact outside exact capture: " + file);
    return resolve(media, file.slice(prefix.length));
  };
  const result = validateExperienceEvidence({
    plan, evidence: record, root, revision: capturedSha, readArtifact: ({ file }) => readFileSync(sourcePath(file)),
  });
  if (result.status !== "PASS") throw new Error("Independent evidence did not validate");
  if (mode === "stage") {
    if (git("rev-parse", "HEAD") !== capturedSha) throw new Error("Stage requires the exact capture checkout");
    const objects = new Map();
    for (const { path, sha256 } of references(record)) {
      if (objects.has(path) && objects.get(path) !== sha256) throw new Error("Conflicting file identity " + path);
      objects.set(path, sha256);
    }
    let total = 0;
    for (const [path, sha256] of objects) {
      const source = sourcePath(path);
      const bytes = readFileSync(source);
      total += bytes.length;
      if (total > 430 * 1024 * 1024 || createHash("sha256").update(bytes).digest("hex") !== sha256)
        throw new Error("Publication byte bound or digest failed: " + path);
      const destination = resolve(root, path);
      mkdirSync(dirname(destination), { recursive: true });
      copyFileSync(source, destination);
    }
    for (const name of receipts) copyFileSync(resolve(media, name), resolve(root, prefix, name));
    writeFileSync(resolve(root, recordPath), JSON.stringify(record, null, 2) + "\n");
  }
  console.log(JSON.stringify({
    status: "PASS", mode, capturedSha, baseSha, contracts: plan.contracts.length,
    journeys: record.journeys.length, paired: record.pairedEvidence.cases.length, artifacts: record.artifacts.length,
  }));
}
